"use client";

import { useEffect, useRef, useState } from "react";
import { api } from "../api";
import type { ProviderAccount } from "../types";
import { ModelSelect } from "./ModelSelect";
import { Badge } from "./ui/badge";
import { Button } from "./ui/button";
import { ScrollArea } from "./ui/scroll-area";
import { Tabs, TabsList, TabsTrigger } from "./ui/tabs";
import { Textarea } from "./ui/textarea";

interface ChatMessage {
  id: number | string;
  role: string;
  content: string;
  mode?: string;
}

interface History {
  workspace: string;
  chat_id: string;
  execution_mode: string;
  messages: ChatMessage[];
}

interface Props {
  workspace: string;
  providers: ProviderAccount[];
  width: number;
  onClose: () => void;
}

export function ProjectChat({ workspace, providers, width, onClose }: Props) {
  const cursor = providers.find((item) => item.id === "cursor");
  const [mode, setMode] = useState<"ask" | "agent">("ask");
  const [model, setModel] = useState("");
  const [draft, setDraft] = useState("");
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [executionMode, setExecutionMode] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const bottom = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!workspace) {
      setMessages([]);
      setExecutionMode("");
      return;
    }
    let cancelled = false;
    api<History>(`/api/project-chat?workspace=${encodeURIComponent(workspace)}`)
      .then((payload) => {
        if (cancelled) return;
        setMessages(payload.messages);
        setExecutionMode(payload.execution_mode);
        setError("");
      })
      .catch((err: unknown) => {
        if (!cancelled) setError(err instanceof Error ? err.message : "Could not load the project chat");
      });
    return () => {
      cancelled = true;
    };
  }, [workspace]);

  useEffect(() => {
    bottom.current?.scrollIntoView({ block: "end" });
  }, [messages, busy]);

  async function send() {
    const text = draft.trim();
    if (!text || !workspace || busy) return;
    setDraft("");
    setBusy(true);
    setError("");
    const pending = Date.now();
    setMessages((current) => [
      ...current,
      { id: `user-${pending}`, role: "user", content: text, mode },
      { id: `assistant-${pending}`, role: "assistant", content: "", mode },
    ]);
    try {
      const response = await fetch("/api/project-chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ workspace, message: text, mode, model, provider: "cursor" }),
      });
      if (!response.ok || !response.body) {
        let detail = response.statusText;
        try {
          const payload = (await response.json()) as { detail?: string };
          detail = payload.detail || detail;
        } catch {
          detail = (await response.text()) || detail;
        }
        throw new Error(detail);
      }
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      let assembled = "";
      while (true) {
        const step = await reader.read();
        if (step.done) break;
        buffer += decoder.decode(step.value, { stream: true });
        const chunks = buffer.split("\n\n");
        buffer = chunks.pop() || "";
        for (const chunk of chunks) {
          const line = chunk.split("\n").find((item) => item.startsWith("data:"));
          if (!line) continue;
          const event = JSON.parse(line.slice(5).trim()) as { type?: string; text?: string; content?: string; detail?: string };
          if (event.type === "delta" && event.text) {
            assembled += event.text;
            const next = assembled;
            setMessages((current) => current.map((item) => (item.id === `assistant-${pending}` ? { ...item, content: next } : item)));
          } else if (event.type === "done" && event.content) {
            const next = event.content;
            setMessages((current) => current.map((item) => (item.id === `assistant-${pending}` ? { ...item, content: next } : item)));
          } else if (event.type === "error") {
            throw new Error(event.detail || "The provider chat failed");
          }
        }
      }
    } catch (err) {
      const detail = err instanceof Error ? err.message : "The provider chat failed";
      setError(detail);
      setMessages((current) => current.map((item) => (item.id === `assistant-${pending}` ? { ...item, content: item.content || detail } : item)));
    } finally {
      setBusy(false);
    }
  }

  async function reset() {
    if (!workspace || busy) return;
    await api(`/api/project-chat?workspace=${encodeURIComponent(workspace)}`, { method: "DELETE" });
    setMessages([]);
    setError("");
  }

  const folder = workspace ? workspace.split("/").filter(Boolean).pop() : "";

  return (
    <aside className="flex h-full min-h-0 shrink-0 flex-col border-l border-border bg-card" style={{ width }}>
      <div className="flex items-start justify-between gap-2 border-b border-border px-3 py-2">
        <div className="min-w-0">
          <div className="text-[10px] font-medium uppercase tracking-wider text-muted-foreground">Project chat</div>
          <div className="truncate text-sm">{folder || "No folder"}</div>
        </div>
        <div className="flex items-center gap-1">
          {executionMode && <Badge variant="outline">{executionMode}</Badge>}
          <Button variant="ghost" size="sm" onClick={onClose} type="button">
            Minimize
          </Button>
        </div>
      </div>
      <div className="space-y-2 border-b border-border px-3 py-2">
        <Tabs value={mode} onValueChange={(value) => setMode(value === "agent" ? "agent" : "ask")}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="ask">Ask</TabsTrigger>
            <TabsTrigger value="agent">Do</TabsTrigger>
          </TabsList>
        </Tabs>
        <p className="text-[11px] leading-snug text-muted-foreground">
          {mode === "ask"
            ? "Ask about this folder. The provider stays outside the pipeline and does not edit files."
            : "Tell the provider to change this folder. This does not run a pipeline node."}
        </p>
        <ModelSelect models={cursor?.models ?? []} value={model} onChange={setModel} />
      </div>
      <ScrollArea className="min-h-0 flex-1">
        <div className="space-y-3 px-3 py-3">
          {!workspace && <p className="text-xs text-muted-foreground">Choose a project folder, then ask about it or have the provider change it.</p>}
          {workspace && messages.length === 0 && !busy && (
            <p className="text-xs text-muted-foreground">No messages yet. This chat is saved on the folder, separate from agent nodes.</p>
          )}
          {messages.map((message) => (
            <div key={message.id} className={message.role === "user" ? "ml-6" : "mr-4"}>
              <div className="mb-1 flex items-center gap-2">
                <span className="font-mono text-[10px] uppercase text-muted-foreground">{message.role === "user" ? "You" : "Cursor"}</span>
                {message.mode && <Badge variant={message.mode === "agent" ? "do" : "ask"}>{message.mode === "agent" ? "do" : "ask"}</Badge>}
              </div>
              <div className={`whitespace-pre-wrap rounded-md px-2.5 py-2 text-sm leading-snug ${message.role === "user" ? "bg-accent" : "bg-background"}`}>
                {message.content || (busy ? "…" : "")}
              </div>
            </div>
          ))}
          <div ref={bottom} />
        </div>
      </ScrollArea>
      {error && <p className="border-t border-destructive/40 px-3 py-1 text-[11px] text-destructive">{error}</p>}
      <form
        className="space-y-2 border-t border-border p-3"
        onSubmit={(event) => {
          event.preventDefault();
          void send();
        }}
      >
        <Textarea
          value={draft}
          placeholder={workspace ? (mode === "ask" ? "Ask about this project" : "What should the provider change?") : "Choose a folder first"}
          disabled={!workspace || busy}
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter" && !event.shiftKey) {
              event.preventDefault();
              void send();
            }
          }}
        />
        <div className="flex items-center justify-between gap-2">
          <Button variant="ghost" size="sm" disabled={!workspace || busy || messages.length === 0} onClick={() => void reset()} type="button">
            New chat
          </Button>
          <Button size="sm" disabled={!workspace || busy || !draft.trim()} type="submit">
            {busy ? "Sending…" : "Send"}
          </Button>
        </div>
      </form>
    </aside>
  );
}
